import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const s = input[0];
const n = s.length;

// 中心から左右に広げられるだけ広げ、その回文の長さを返す
function expand(left: number, right: number): number {
  while (left >= 0 && right < n && s[left] === s[right]) {
    left--;
    right++;
  }
  return right - left - 1;
}

let best = 1;
for (let c = 0; c < n; c++) {
  best = Math.max(best, expand(c, c)); // 長さが奇数の回文（中心が 1 文字）
  best = Math.max(best, expand(c, c + 1)); // 長さが偶数の回文（中心が文字の間）
}
console.log(best);
